-- duckdb: slim person files from IPUMS International extracts (ke2009a, ke2019a, mx2010a, mx2020a) converted to parquet.
PRAGMA threads=4;
COPY (SELECT YEARP, SERIALP, PERWT, AGE, SEX, SCHOOL, EDATTAIN, DISABLED, DISMNTL, KE2019A_0450, KE2019A_0469, KE2019A_0470, KE2019A_0471, KE2019A_0472, HHWT_H, URBAN_H, GEOLEV2_H, GEO2_KE_H AS GEO2, CELL_H, INTERNET_H, KE2019A_0121_H, KE2019A_0122_H FROM read_parquet('data/ipums/ipumsi/ke2019a.parquet')) TO 'data/extracts/ipumsi/ke2019a_slim.parquet' (FORMAT PARQUET, COMPRESSION ZSTD);
COPY (SELECT YEARP, SERIALP, PERWT, AGE, SEX, SCHOOL, EDATTAIN, DISABLED, DISMNTL, KE2009A_0431, KE2009A_0440, KE2009A_0443, KE2009A_0444, HHWT_H, URBAN_H, GEOLEV2_H, GEO2_KE_H AS GEO2, CELL_H, KE2009A_0061_H FROM read_parquet('data/ipums/ipumsi/ke2009a.parquet')) TO 'data/extracts/ipumsi/ke2009a_slim.parquet' (FORMAT PARQUET, COMPRESSION ZSTD);
COPY (SELECT YEARP, SERIALP, PERWT, AGE, SEX, SCHOOL, LIT, EDATTAIN, DISABLED, DISMNTL, DISPSYC, MX2020A_0421, MX2020A_0424, MX2020A_0428, HHWT_H, URBAN_H, GEOLEV2_H, GEO2_MX_H AS GEO2, CELL_H, INTERNET_H, COMPUTER_H, MX2020A_0069_H, MX2020A_0071_H, MX2020A_0072_H FROM read_parquet('data/ipums/ipumsi/mx2020a.parquet')) TO 'data/extracts/ipumsi/mx2020a_slim.parquet' (FORMAT PARQUET, COMPRESSION ZSTD);
COPY (SELECT YEARP, SERIALP, PERWT, AGE, SEX, SCHOOL, LIT, EDATTAIN, DISABLED, DISMNTL, MX2010A_0422, HHWT_H, URBAN_H, GEOLEV2_H, GEO2_MX_H AS GEO2, CELL_H, INTERNET_H, COMPUTER_H, MX2010A_0056_H, MX2010A_0058_H, MX2010A_0059_H FROM read_parquet('data/ipums/ipumsi/mx2010a.parquet')) TO 'data/extracts/ipumsi/mx2010a_slim.parquet' (FORMAT PARQUET, COMPRESSION ZSTD);
